new:
// Use an empty lang_pack in initConnection with the fork's API ID.
// App translations still use the existing iOS localization catalog.
apiEnvironment.langPack = ""

// This IPA is signed by the installer, so Telegram's APNS login
// verification is unavailable. Request the normal code delivery
// flow without advertising a push token for Firebase SMS.
let authorizationPushConfiguration: Signal<AuthorizationCodePushNotificationConfiguration?, NoError> = .single(nil)
